import{_ as p,r as n,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Введение - October CMS - 3.x","titleTemplate":false,"description":"October CMS поставляется с простым и лёгким AJAX-фреймворком.","frontmatter":{"subtitle":"October CMS поставляется с простым и лёгким AJAX-фреймворком."},"headers":[{"level":2,"title":"Подключение фреймворка","slug":"подключение-фреимворка","link":"#подключение-фреимворка","children":[{"level":3,"title":"Дополнительные возможности","slug":"дополнительные-возможности","link":"#дополнительные-возможности","children":[]}]},{"level":2,"title":"Как работают AJAX-запросы","slug":"как-работают-ajax-запросы","link":"#как-работают-ajax-запросы","children":[]},{"level":2,"title":"Пример использования","slug":"пример-использования","link":"#пример-использования","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}],"relativePath":"3.x/ru/cms/ajax/introduction.md","filePath":"3.x/ru/cms/ajax/introduction.md"}'),u={name:"3.x/ru/cms/ajax/introduction.md"};function r(k,a,g,d,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Введение",-1)),s(e),a[1]||(a[1]=i(`<p>October CMS включает AJAX-фреймворк, предоставляющий полный набор возможностей, позволяющий загружать данные с сервера без обновления страницы в браузере. Эта же библиотека может использоваться в CMS-темах и в любом месте панели администрирования.</p><p>AJAX-фреймворк представлен в двух вариантах: вы можете использовать <a href="./javascript-api.html">JavaScript API</a> или <a href="./attributes-api.html">API атрибутов данных</a>. API атрибутов данных не требует знания JavaScript для использования AJAX в October CMS.</p><h2 id="подключение-фреимворка"><a href="#подключение-фреимворка" class="header-anchor">#</a> Подключение фреймворка</h2><div class="custom-block aside"><p>AJAX-фреймворк является необязательным в вашей CMS-теме, и вы всегда можете подключить предпочитаемый вами фреймворк вместо него.</p></div><p>При работе с <a href="./../../cms/themes/themes.html">CMS-темой</a> подключение библиотеки сводится к использованию Twig-тега. Разместите тег <code>{% framework %}</code> в любом месте вашей страницы или макета. Это добавит ссылку на фронтенд-библиотеку JavaScript October CMS, например:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="дополнительные-возможности"><a href="#дополнительные-возможности" class="header-anchor">#</a> Дополнительные возможности</h3><p>Тег <code>{% framework %}</code> поддерживает необязательный параметр <strong>extras</strong>, который подключает дополнительные файлы стилей и JavaScript для расширенных функций, включая <a href="./../features/validation.html">валидацию форм</a>, <a href="./../features/loaders.html">индикаторы загрузки</a> и <a href="./../features/flash-messages.html">flash-сообщения</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете добавить параметр <strong>turbo</strong> для включения <a href="./turbo-router.html">турбо-маршрутизации</a> на каждой странице.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras turbo <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="как-работают-ajax-запросы"><a href="#как-работают-ajax-запросы" class="header-anchor">#</a> Как работают AJAX-запросы</h2><p>Страница может отправить AJAX-запрос с помощью атрибутов данных или JavaScript. Каждый запрос вызывает <strong>обработчик событий</strong> — также называемый <a href="./handlers.html">AJAX-обработчиком</a> — на сервере и может обновлять элементы страницы с помощью фрагментов. AJAX-запросы лучше всего работают с формами, поскольку данные формы автоматически отправляются на сервер. Вот рабочий процесс запроса:</p><ol><li>Клиентский браузер отправляет AJAX-запрос, указывая имя обработчика и другие необязательные параметры.</li><li>Сервер находит <a href="./handlers.html">AJAX-обработчик</a> и выполняет его.</li><li>Обработчик выполняет необходимую бизнес-логику и обновляет окружение, внедряя переменные страницы.</li><li>Сервер <a href="./update-partials.html">рендерит фрагменты</a>, запрошенные клиентом с помощью опции <code>update</code>.</li><li>Сервер отправляет ответ, содержащий отрендеренную разметку фрагментов.</li><li>Клиентский фреймворк обновляет элементы страницы данными фрагментов, полученными от сервера.</li></ol><h2 id="пример-использования"><a href="#пример-использования" class="header-anchor">#</a> Пример использования</h2><p>Ниже приведён простой пример, использующий API атрибутов данных для определения формы с поддержкой AJAX. Форма отправит AJAX-запрос обработчику <strong>onTest</strong> и запросит обновление контейнера результата разметкой фрагмента <strong>mypartial</strong>.</p><div class="custom-block tip"><p>Данные формы для <code>value1</code> и <code>value2</code> автоматически отправляются вместе с AJAX-запросом.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- AJAX enabled form --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mypartial: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Input two values --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span> + <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Action button --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Calculate<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- Result container --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Фрагмент <strong>mypartial</strong> содержит разметку, которая считывает переменную <code>result</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The answer is <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Метод обработчика <strong>onTest</strong> получает данные формы с помощью вспомогательного метода <code>input</code> (<a href="./../../extend/services/helpers.html">helper-метод</a>), и результат передаётся в переменную страницы <code>result</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Пример можно прочитать так: «Когда форма отправлена, выполнить AJAX-запрос к обработчику <strong>onTest</strong>. Когда обработчик завершит работу, отрендерить фрагмент <strong>mypartial</strong> и вставить его содержимое в элемент <strong>#myDiv</strong>».</p><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./javascript-api.html">JavaScript API</a></li><li><a href="./attributes-api.html">API атрибутов данных</a></li></ul></div>`,24))])}const A=p(u,[["render",r]]);export{f as __pageData,A as default};
